44	    /**
45	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
46	     * last names, as required by the API's read-only {@code displayName} field.
47	     *
48	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
49	     * applied only where referenced via {@code qualifiedByName}.
50	     */
51	    @Named("formatDisplayName")
52	    default String formatDisplayName(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        return owner.getLastName() + ", " + owner.getFirstName();
57	    }
58	
59	    /**
60	     * Formats an owner's initials as the upper-cased first letters of the first and last
61	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
62	     * API's read-only {@code initials} field.
63	     *
64	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
65	     * applied only where referenced via {@code qualifiedByName}.
66	     */
67	    @Named("formatInitials")
68	    default String formatInitials(Owner owner) {
69	        if (owner == null) {
70	            return null;
71	        }
72	        return initial(owner.getFirstName()) + initial(owner.getLastName());
73	    }
74	
75	    /**
76	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
77	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
78	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
79	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
80	     * telephone is present.
81	     *
82	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
83	     * applied only where referenced via {@code qualifiedByName}.
84	     */
85	    @Named("formatTelephoneDisplay")
86	    default String formatTelephoneDisplay(Owner owner) {
87	        if (owner == null) {
88	            return null;
89	        }
90	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
91	    }
92	
93	    /**
94	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
95	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
96	     * {@code YY} is the last two digits of the registration date's year (e.g.
97	     * {@code 'NSW-1A2B3C4D-M26'}), as required by the API's read-only
98	     * {@code membershipNumber} field. Returns {@code null} when either the customer code
99	     * or registration date is absent.
100	     *
101	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
102	     * applied only where referenced via {@code qualifiedByName}.
103	     */
104	    @Named("formatMembershipNumber")
105	    default String formatMembershipNumber(Owner owner) {
106	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
107	            return null;
108	        }
109	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
110	    }
111	
112	    /**
113	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
114	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
115	     * code. Returns {@code null} when the customer code is absent.
116	     *
117	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
118	     * applied only where referenced via {@code qualifiedByName}.
119	     */
120	    @Named("formatCheckDigit")
121	    default Integer formatCheckDigit(Owner owner) {
122	        if (owner == null || owner.getCustomerCode() == null) {
123	            return null;
124	        }
125	        return LuhnCheckDigit.compute(owner.getCustomerCode());
126	    }
127	
128	    /**
129	     * Computes an owner's membership points, as required by the API's read-only
130	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
131	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
132	     * of 3 or more members, plus 3 when the owner's tenure exceeds 365 days (more than a year
133	     * since the registration date).
134	     *
135	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
136	     * applied only where referenced via {@code qualifiedByName}.
137	     */
138	    @Named("formatMembershipPoints")
139	    default Integer formatMembershipPoints(Owner owner) {
140	        if (owner == null) {
141	            return null;
142	        }
143	        int points = 0;
144	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
145	            points += 2;
146	        }
147	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
148	            points += 1;
149	        }
150	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
151	            points += 2;
152	        }
153	        if (owner.getRegistrationDate() != null
154	                && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365) {
155	            points += 3;
156	        }
157	        return points;
158	    }
159	
160	    /**
161	     * Derives an owner's membership level, as required by the API's read-only
162	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
163	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
164	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
165	     *
166	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
167	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
168	     * to record the membership level on the create audit line).
169	     */
170	    @Named("formatMembershipLevel")
171	    default Integer formatMembershipLevel(Owner owner) {
172	        if (owner == null) {
173	            return null;
174	        }
175	        int points = formatMembershipPoints(owner);
176	        if (points <= 1) {
177	            return 1;
178	        }
179	        if (points <= 3) {
180	            return 2;
181	        }
182	        if (points <= 5) {
183	            return 3;
184	        }
185	        return 4;
186	    }
187	
188	    /**
189	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
190	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
191	     * locality is read from the same region-and-hash identity that the customer code encodes.
192	     * When no customer code is present (e.g. an owner that predates the code), the region is
193	     * resolved directly from the postcode (falling back to the city-to-region table, else
194	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
195	     *
196	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
197	     * applied only where referenced via {@code qualifiedByName}.
198	     */
199	    @Named("formatLocality")
200	    default String formatLocality(Owner owner) {
201	        if (owner == null) {
202	            return null;
203	        }
204	        String customerCode = owner.getCustomerCode();
205	        if (customerCode != null) {
206	            int dash = customerCode.indexOf('-');
207	            if (dash > 0) {
208	                return customerCode.substring(0, dash);
209	            }
210	        }
211	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
212	    }
213	
214	    /**
215	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
216	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
217	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
218	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
219	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
220	     *
