227	            return null;
228	        }
229	        return LocalityResolver.timezone(formatLocality(owner));
230	    }
231	
232	    /**
233	     * Derives an owner's preferred contact channel, as required by the API's read-only
234	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
