241	    default String formatContactPreference(Owner owner) {
242	        if (owner == null) {
243	            return null;
244	        }
245	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
246	    }
247	
248	    /**
249	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
250	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
251	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
