261	            return null;
262	        }
263	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
264	        if (age < 18) {
265	            return "MINOR";
266	        }
267	        if (age < 65) {
268	            return "ADULT";
269	        }
270	        return "SENIOR";
271	    }
