296	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
297	     * only where referenced via {@code qualifiedByName}.
298	     */
299	    @Named("normalizeAddress")
300	    default String normalizeAddress(String address) {
301	        return AddressNormalizer.normalize(address);
302	    }
303	
304	    /**
305	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
306	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
307	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
308	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
309	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
310	     *
311	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
312	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
313	     *
314	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
315	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
316	     */
